(function(E){ const x = E["int-m2"] = E["int-m2"] || {units:{}}; x.units["int-6"] = {"grammar":{"id":"c-int-6-g","level":"B1","course":"interview","unit":"int-6","title":"Problems right now: present continuous","titleTr":"Şu anki sorunlar: present continuous","titleFa":"مشکلِ همین الان: حال استمراری","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["A problem now: am / is / are + -ing","You're breaking up."],["Negative","I'm not getting any sound."],["Question","Is my sound working now?"],["Always true: present simple","My laptop has a good camera."]]},"wrong":"Sorry, your video freezes right now.","right":"Sorry, your video is freezing right now.","blank":{"sentence":"Sorry, can you hear me? My screen ___ right now.","word":"is freezing","distractors":["freezes","freeze"]},"wrong2":"We are lose the connection again.","right2":"We are losing the connection again.","blank2":{"sentence":"Sorry, I ___ any sound at the moment.","word":"am not getting","distractors":["don't get","not getting"]},"expParts":{"rule":[{"en":"For a problem happening now, use am / is / are + -ing.","tr":"Şu anda olan bir sorun için am / is / are + -ing kullan.","fa":"برای مشکلی که همین الان هست am، is یا are را با فعل ing می‌آوری.","ex":"You're breaking up."},{"en":"Add not to say what isn't working.","tr":"Çalışmayan şeyi söylemek için not ekle.","fa":"برای گفتن چیزی که کار نمی‌کند، بعد از am، is یا are کلمه‌ی not را بیاور.","ex":"I'm not getting any sound."},{"en":"For something always true, use the present simple.","tr":"Her zaman doğru olan bir şey için present simple kullan.","fa":"برای چیزی که همیشه درست است حال ساده می‌آوری.","ex":"My laptop has a good camera."}],"test":{"en":"Can you add 'right now'? Then use am / is / are + -ing.","tr":"Cümleye 'right now' ekleyebiliyor musun? O zaman am / is / are + -ing kullan.","fa":"می‌توانی «right now» را به جمله اضافه کنی؟ پس am / is / are + ‎-ing بیاور."},"contrast":{"en":"Persian uses one present tense for 'now' and 'always', so learners say 'You break up'. Turkish -iyor matches: kesiliyor = is cutting out.","tr":"Türkçedeki '-iyor' burada yardımcı olur: 'ses kesiliyor' = the sound is cutting out. Tuzak, 'You break up' gibi yalın biçimdir.","fa":"در فارسی «صدایت قطع و وصل می‌شود» هم برای «الان» است و هم برای «همیشه»؛ برای همین «You break up» می‌گوییم. انگلیسی برای «همین الان» am، is یا are را با فعل ing می‌آورد: You're breaking up."}},"errorWatch":[{"find":["you break up","freezes right now","cuts out right now","i not getting","we are lose","is freeze","are break","is cut out"],"fix":{"en":"For a problem happening now, use am / is / are + -ing: 'You're breaking up', 'The screen is freezing'.","tr":"Şu anda olan bir sorun için am / is / are + -ing kullan: 'You're breaking up', 'The screen is freezing'.","fa":"برای مشکلی که همین الان هست از am / is / are + ‎-ing استفاده کن: «You're breaking up»، «The screen is freezing»."}}]},"b2":{"id":"c-int-6-b2","level":"B2","track":"B2","course":"interview","unit":"int-6","title":"Looking back: should have, could have","titleTr":"Geriye bakmak: should have, could have","titleFa":"نگاه به گذشته: should have و could have","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["should have + past participle: you didn't do it","I should have tested my internet."],["shouldn't have + past participle: you did it","I shouldn't have read my notes."],["could have + past participle: a missed chance","I could have asked about the team."]]},"wrong":"I should have test the camera before the call.","right":"I should have tested the camera before the call.","blank":{"sentence":"He ___ looked at the camera, not at his own face.","word":"should have","distractors":["should","must"]},"wrong2":"I shouldn't read my notes during yesterday's interview.","right2":"I shouldn't have read my notes during yesterday's interview.","blank2":{"sentence":"I ___ asked about the team, but I said I had no questions.","word":"could have","distractors":["can have","could"]},"useIn":{"en":"B2: in your writing or speaking, add one sentence that looks back: 'I should have...' or 'I could have...'.","tr":"B2: yazında ya da konuşmanda geriye bakan bir cümle ekle: 'I should have...' ya da 'I could have...'.","fa":"در مسیر B2: در نوشته یا صحبتت جمله‌ای اضافه کن که به گذشته نگاه می‌کند: «I should have...» یا «I could have...»."},"exitItem":{"from":"int-6","kind":"blank","prompt":"The call dropped twice. I ___ a quieter room with better Wi-Fi.","options":["should have booked","should book","should have book"],"correct":0,"why":{"en":"should have booked: a past action you didn't do but should have: should + have + past participle. 'Should book' is about now, and 'should have book' drops -ed.","tr":"should have booked: yapmadığın ama yapman gereken geçmiş bir eylem: should + have + üçüncü hâl. 'Should book' şimdiyle ilgilidir; 'should have book' -ed'i düşürür.","fa":"should have booked درست است، چون کاری در گذشته بود که باید می‌کردی و نکردی: should و have و اسم مفعول. should book درباره‌ی الان است و should have book ‎-ed ندارد."}},"expParts":{"rule":[{"en":"Didn't do it, but it was a good idea: should have + past participle.","tr":"Yapmadın ama iyi bir fikirdi: should have + üçüncü hâl.","fa":"should have همان «باید ... می‌کردم» فارسی است: کاری که باید می‌کردی و نکردی.","ex":"I should have tested my internet."},{"en":"Did it, but it was a bad idea: shouldn't have.","tr":"Yaptın ama kötü bir fikirdi: shouldn't have.","fa":"اگر کاری را کردی و فکر بدی بود، می‌گویی shouldn't have.","ex":"I shouldn't have read my notes."},{"en":"A chance you missed: could have.","tr":"Kaçırdığın bir fırsat: could have.","fa":"برای فرصتی که از دست دادی could have می‌آوری.","ex":"I could have asked about the team."}],"test":{"en":"Is it about the past? Then have + past participle after should or could.","tr":"Geçmişle mi ilgili? O zaman should ya da could'dan sonra have + üçüncü hâl.","fa":"درباره‌ی گذشته است؟ پس بعد از should یا could، کلمه‌ی have و اسم مفعول بیاور."},"contrast":{"en":"Turkish '-meliydim' and Persian 'باید ... می‌کردم' put the past inside one verb. English splits it: should + have + past participle.","tr":"Türkçedeki '-meliydim' geçmişi tek bir fiilde verir. İngilizce bunu böler: should + have + üçüncü hâl.","fa":"در فارسی «باید ... می‌کردم» گذشته را در خود فعل دارد. انگلیسی آن را جدا می‌کند: اول should، بعد have و بعد اسم مفعول."}},"errorWatch":[{"find":["should have test","should have look","should have ask","should have check","should have use","could have ask","should of","could of"],"fix":{"en":"After should have / could have, use the past participle: 'I should have tested the camera.'","tr":"should have / could have'den sonra üçüncü hâli kullan: 'I should have tested the camera.'","fa":"بعد از should have / could have اسم مفعول بیاور: «I should have tested the camera.‎»"}}]},"vocab":{"id":"c-int-6-v","level":"B1","category":"vocab","course":"interview","unit":"int-6","goals":["career"],"title":{"en":"Video and Recorded Interviews","tr":"Görüntülü ve Kayıtlı Mülakatlar","fa":"مصاحبه‌های تصویری و ضبط‌شده"},"cards":[{"word":"connection","sentence":"Test your internet connection the day before.","meaning":{"en":"The link between your device and the internet.","tr":"bağlantı.","fa":"اتصال؛ ارتباط اینترنتی"}},{"word":"camera","sentence":"Put the camera at the height of your eyes.","meaning":{"en":"The part of a phone or laptop that takes your picture.","tr":"kamera.","fa":"دوربین"}},{"word":"on mute","sentence":"Sorry, I think you're on mute.","meaning":{"en":"With the microphone turned off.","tr":"sesi kapalı.","fa":"بی‌صدا؛ با میکروفون خاموش"}},{"word":"recorded interview","sentence":"In a recorded interview, nobody is on the call with you.","meaning":{"en":"An interview where you record answers alone and the company watches them later.","tr":"Cevaplarını tek başına kaydettiğin ve şirketin sonra izlediği mülakat.","fa":"مصاحبه‌ای که جواب‌ها را تنها ضبط می‌کنی و شرکت بعداً آن‌ها را می‌بیند."}},{"word":"background","sentence":"Choose a quiet room with a plain background.","meaning":{"en":"Here: what people can see behind you on a video call.","tr":"burada: görüntülü görüşmede arkanda görünenler.","fa":"اینجا: چیزی که در تماس تصویری پشت سرت دیده می‌شود"}},{"word":"retake","sentence":"This company allows one retake for each question.","meaning":{"en":"A second try at recording an answer.","tr":"Bir cevabı yeniden kaydetme hakkı.","fa":"فرصت دوباره برای ضبط یک جواب."}},{"word":"frozen","sentence":"Your picture is frozen, but I can still hear you.","meaning":{"en":"Here: not moving because the video has stopped.","tr":"burada: görüntü donmuş.","fa":"اینجا: تصویری که ثابت مانده و حرکت نمی‌کند"}},{"word":"break up","sentence":"Sorry, you're breaking up. Could you say that again?","meaning":{"en":"When a voice on a call keeps cutting out.","tr":"(ses) kesik kesik gelmek.","fa":"قطع و وصل شدن صدا"},"gap":"breaking up","accept":["breaking up"]},{"word":"headphones","sentence":"Headphones stop the echo on a video call.","meaning":{"en":"Small speakers you wear on or in your ears.","tr":"kulaklık.","fa":"هدفون"}},{"word":"link","sentence":"I'll send you the link ten minutes before the call.","meaning":{"en":"The web address you click to join a call.","tr":"bağlantı linki.","fa":"لینک"}}]},"judge":{"id":"c-int-6-j","course":"interview","unit":"int-6","type":"judge","title":{"en":"When the call goes wrong","tr":"Görüşme aksayınca","fa":"وقتی تماس مشکل پیدا می‌کند"},"prompt":"Five things candidates said when something went wrong on a video call.","parts":["Says what the problem is","Asks for something clear","Moves on quickly"],"instruction":{"en":"Tap what each line does. The strongest line does all three.","tr":"Her cümlenin ne yaptığına dokun. En güçlü cümle üçünü de yapar.","fa":"روی کاری که هر جمله می‌کند بزن. قوی‌ترین جمله هر سه را انجام می‌دهد."},"items":[{"by":"Graduate","answer":"Oh no, I'm so sorry, I'm really so sorry, this never happens, my internet is very bad today, I'm terribly sorry.","present":["Says what the problem is"],"fix":{"en":"One apology is enough. Five apologies use up your time and your confidence. Say it once, then go back to the answer.","tr":"Bir özür yeter. Beş özür hem zamanını hem özgüvenini tüketir. Bir kez söyle, sonra cevabına dön.","fa":"یک عذرخواهی کافی است. پنج عذرخواهی هم وقتت را می‌گیرد هم اعتمادبه‌نفست را. یک بار بگو و برگرد سر جوابت."}},{"by":"Accountant","answer":"Hello? Hello? Can you... hello?","present":[],"fix":{"en":"They can't tell what is wrong. Say it and ask: \"I can't hear you. Could you say that again?\"","tr":"Neyin yanlış olduğunu anlayamıyorlar. Söyle ve iste: \"I can't hear you. Could you say that again?\"","fa":"آن‌ها نمی‌فهمند مشکل چیست. بگو مشکل چیست و درخواستت را مطرح کن: «I can't hear you. Could you say that again?»"}},{"by":"Engineer","answer":"Your voice breaks.","present":["Says what the problem is"],"fix":{"en":"The form is wrong for a problem right now, and it sounds rude. Say: \"Sorry, you're breaking up. Could you say that again?\"","tr":"Şu anda olan bir sorun için bu yapı yanlış ve kaba duruyor. Şöyle de: \"Sorry, you're breaking up. Could you say that again?\"","fa":"این ساختار برای مشکلی که همین حالا هست غلط است و بی‌ادبانه به نظر می‌رسد. بگو: «Sorry, you're breaking up. Could you say that again?»"}},{"by":"Sales assistant","answer":"My connection dropped. Okay, next question, please.","present":["Says what the problem is","Moves on quickly"],"fix":{"en":"Calm, but they may have missed your best sentence. Check first: \"How much of my last answer did you hear?\"","tr":"Sakin, ama en iyi cümleni kaçırmış olabilirler. Önce sor: \"How much of my last answer did you hear?\"","fa":"آرام است، ولی شاید بهترین جمله‌ات را نشنیده باشند. اول بپرس: «How much of my last answer did you hear?»"}},{"by":"Good model","answer":"Sorry about that, my connection dropped. How much of my last answer did you hear? I can start it again.","present":["Says what the problem is","Asks for something clear","Moves on quickly"],"fix":null}]},"speaking":{"id":"int-6","course":"interview","unit":"int-6","topic":{"en":"A live call and a recorded answer","tr":"Canlı görüşme ve kayıtlı cevap","fa":"تماس زنده و جواب ضبط‌شده"},"warmup":{"en":"Open your phone camera. Put it at eye level. Look at the lens and say your name and your job.","tr":"Telefonunun kamerasını aç. Göz hizasına koy. Merceğe bak, adını ve işini söyle.","fa":"دوربین گوشی‌ات را باز کن. آن را هم‌سطح چشمت بگذار. به لنز نگاه کن و اسم و شغلت را بگو."},"questions":[{"en":"Start the call: check that they can hear you, and that you can hear them.","tr":"Görüşmeyi başlat: seni duyduklarını ve senin de onları duyduğunu kontrol et.","fa":"تماس را شروع کن: مطمئن شو صدایت را می‌شنوند و تو هم صدایشان را می‌شنوی."},{"en":"\"Tell me about yourself.\" Answer while looking at the camera, not at your own face.","tr":"\"Tell me about yourself.\" Kendi yüzüne değil, kameraya bakarak cevap ver.","fa":"«Tell me about yourself.» جواب بده و نگاهت به دوربین باشد، نه به تصویر خودت."},{"en":"The sound cuts out. Say what is happening and politely ask them to repeat.","tr":"Ses kesiliyor. Ne olduğunu söyle ve kibarca tekrar etmelerini iste.","fa":"صدا قطع می‌شود. بگو چه اتفاقی افتاده و مؤدبانه بخواه تکرار کنند."},{"en":"Your connection dropped and you are back. Apologise once, and continue.","tr":"Bağlantın koptu ve geri döndün. Bir kez özür dile ve devam et.","fa":"اتصالت قطع شده و برگشته‌ای. یک بار عذرخواهی کن و ادامه بده."},{"en":"Recorded round: read \"Why do you want this job?\", think for 30 seconds, then answer in 60 seconds. Record it and watch it once.","tr":"Kayıt turu: \"Why do you want this job?\" sorusunu oku, 30 saniye düşün, sonra 60 saniyede cevap ver. Kaydet ve bir kez izle.","fa":"دور ضبط: «Why do you want this job?» را بخوان، ۳۰ ثانیه فکر کن و بعد در ۶۰ ثانیه جواب بده. ضبطش کن و یک بار ببین."}],"followups":[{"en":"Do the live part again in 60 seconds, then 45. One apology, not five.","tr":"Canlı kısmı önce 60, sonra 45 saniyede yeniden yap. Beş değil, bir özür.","fa":"بخش زنده را دوباره در ۶۰ و بعد ۴۵ ثانیه انجام بده. یک بار عذرخواهی کن، نه پنج بار."}],"expressions":[{"phrase":"Can you hear me okay?","meaning":{"en":"Your first line on any call.","tr":"Her görüşmedeki ilk cümlen.","fa":"جمله‌ی اولت در هر تماس."}},{"phrase":"Sorry, you're breaking up.","meaning":{"en":"Says the sound is cutting out.","tr":"Sesin kesildiğini söyler.","fa":"می‌گوید صدا قطع و وصل می‌شود."}},{"phrase":"Sorry about that, my connection dropped.","meaning":{"en":"One apology, then you continue.","tr":"Bir özür, sonra devam edersin.","fa":"یک عذرخواهی و بعد ادامه می‌دهی."}}],"selfCheck":[{"en":"I checked the sound in my first sentence.","tr":"İlk cümlemde sesi kontrol ettim.","fa":"در جمله‌ی اولم صدا را امتحان کردم."},{"en":"I looked at the camera for my most important sentences.","tr":"En önemli cümlelerimde kameraya baktım.","fa":"برای مهم‌ترین جمله‌هایم به دوربین نگاه کردم."},{"en":"I apologised once, not many times.","tr":"Bir kez özür diledim, defalarca değil.","fa":"یک بار عذرخواهی کردم، نه چند بار."},{"en":"My recorded answer ended before the timer.","tr":"Kayıtlı cevabım süre bitmeden sona erdi.","fa":"جواب ضبط‌شده‌ام پیش از پایان زمان تمام شد."}],"model":"Hello, can you hear me okay? Great, I can hear you too. Yes, thanks. The link was clear. Sorry, you're breaking up. Could you say the last part again? Thank you. Sorry about that, my connection dropped. Where were we? Yes, why this job. I'm applying because your team works with clients abroad, and I want to use my English every day."},"writing":{"id":"c-int-6-w","course":"interview","unit":"int-6","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"model":"Dear Mr Kaya,\n\nI am sorry that our call ended early today. My internet connection dropped, and I could not get back into the meeting. I am still very interested in the position. I am available to talk tomorrow morning or at any time on Friday, and you can also reach me on 0532 000 00 00.\n\nThank you for your time.\n\nKind regards,\nYour name","frame":"Dear ___,\n\nI am sorry that ___. My ___, and I could not ___. I am still very interested in ___. I am available ___, and you can also reach me on ___.\n\nThank you for ___.\n\nKind regards,\n___","words":[{"word":"connection"},{"word":"available"}],"minWords":50,"minSentences":4,"title":{"en":"Your email after the call dropped","tr":"Görüşme koptuktan sonra e-postan","fa":"ایمیل تو بعد از قطع شدن تماس"},"prompt":{"en":"Your video interview dropped and you could not reconnect. Write a short email to the interviewer (50-80 words): apologise briefly, say what happened, say when you are available, give your phone number and thank them.","tr":"Görüntülü mülakatın koptu ve yeniden bağlanamadın. Mülakatı yapan kişiye kısa bir e-posta yaz (50-80 kelime): kısaca özür dile, ne olduğunu söyle, ne zaman müsait olduğunu belirt, telefon numaranı ver ve teşekkür et.","fa":"مصاحبه‌ی تصویری‌ات قطع شد و نتوانستی دوباره وصل شوی. یک ایمیل کوتاه به مصاحبه‌کننده بنویس (۵۰ تا ۸۰ کلمه): کوتاه عذرخواهی کن، بگو چه شد، بگو کی وقت داری، شماره‌تلفنت را بده و تشکر کن."},"rubric":["Task done: a short apology, what happened, when you are available, a phone number, thanks","Organised: apology, reason, availability, contact, close","Language: past simple for what happened; \"I'm available to\" + verb","Tone: calm and professional: one apology, no long excuses"],"rubricI18n":{"tr":["Görev: kısa bir özür, ne olduğu, ne zaman müsait olduğun, telefon numarası, teşekkür","Düzen: özür, neden, müsaitlik, iletişim, kapanış","Dil: olanlar için past simple; \"I'm available to\" + fiil","Üslup: sakin ve profesyonel: tek özür, uzun bahaneler yok"],"fa":["کامل بودن کار: یک عذرخواهی کوتاه، چه اتفاقی افتاد، کی وقت داری، شماره‌تلفن، تشکر","نظم: عذرخواهی، دلیل، زمان آزاد، راه تماس، پایان","زبان: گذشته‌ی ساده برای اتفاق؛ «I'm available to» با فعل ساده","لحن: آرام و حرفه‌ای؛ یک عذرخواهی، بدون بهانه‌های طولانی"]}},"exit":{"id":"c-int-6-x","course":"interview","unit":"int-6","type":"exit","items":[{"from":"int-6","kind":"blank","prompt":"Hold on, my laptop ___ an update right now.","options":["is installing","installs","install"],"correct":0,"point":2,"why":{"en":"is installing: 'right now' means the action is happening at this moment, so use am/is/are + -ing. 'Installs' is a habit, and 'install' doesn't agree with 'my laptop'.","tr":"is installing: 'right now' eylemin şu anda olduğunu gösterir, bu yüzden am/is/are + -ing. 'Installs' alışkanlıktır; 'install' 'my laptop' ile uyuşmaz.","fa":"is installing درست است، چون right now یعنی همین الان در جریان است و am/is/are و فعل ing‌دار لازم است. installs عادت است و install با my laptop جور نیست."}},{"from":"int-6","kind":"blank","prompt":"Your picture ___ at the moment. Could you turn your camera off and on again?","options":["froze","is freezing","freezes"],"correct":1,"point":2,"why":{"en":"is freezing: 'at the moment' is a problem happening now. 'Froze' is finished, and 'freezes' is something that always happens.","tr":"is freezing: 'at the moment' şu anda olan bir sorundur. 'Froze' bitmiştir; 'freezes' her zaman olan bir şeydir.","fa":"is freezing درست است، چون at the moment یعنی مشکل همین الان هست. froze تمام‌شده است و freezes یعنی همیشه این‌طور است."}},{"from":"int-6","kind":"mcq","prompt":"You get a link to a recorded interview. What do you do first?","options":["Start the first question at once, before you get nervous","Read how much think time, answer time and how many retakes you have","Write your answers out in full and read them to the camera"],"correct":1,"point":1,"why":{"en":"Read the rules first: think time, answer time and retakes differ for each employer. Rushing in or reading a script both cost you.","tr":"Önce kuralları oku: düşünme süresi, cevap süresi ve tekrar hakkı her işverende farklıdır. Hemen başlamak da metin okumak da sana kaybettirir.","fa":"اول قواعد را بخوان، چون زمان فکر، زمان جواب و تعداد تکرار برای هر کارفرما فرق دارد. عجله کردن یا خواندن از روی متن هر دو به ضررت است."}},{"from":"int-5","kind":"blank","prompt":"I ___ a report when the fire alarm went off.","options":["was writing","wrote","have written"],"correct":0,"point":2,"why":{"en":"was writing: the long background action takes the past continuous, and the alarm cuts into it. 'Wrote' loses the background, and 'have written' links to now.","tr":"was writing: uzun arka plan eylemi past continuous alır ve alarm onu böler. 'Wrote' arka planı kaybeder; 'have written' şimdiye bağlar.","fa":"was writing درست است، چون کار طولانی پس‌زمینه گذشته‌ی استمراری می‌خواهد و آژیر وسطش رخ می‌دهد. wrote پس‌زمینه را از بین می‌برد و have written به الان ربط دارد."}},{"from":"int-3","kind":"mcq","prompt":"Which small-talk topic is safest before an interview?","options":["Your journey to the office that morning","Who you voted for in the last election","How much people earn at this company"],"correct":0,"point":3,"why":{"en":"Your journey that morning is safe and easy to talk about. Voting and pay are personal topics to avoid before an interview.","tr":"O sabahki yolculuğun güvenli ve konuşması kolay bir konudur. Oy ve maaş, mülakattan önce kaçınılması gereken kişisel konulardır.","fa":"سفرت تا دفتر در همان صبح موضوعی امن و راحت است. رأی و حقوق موضوع‌های شخصی‌اند که قبل از مصاحبه باید از آن‌ها دوری کرد."}},{"from":"int-4","kind":"mcq","prompt":"What do interviewers want from a weakness answer?","options":["To see that you know yourself and can improve","To hear that you have no real faults at work","To find out which main skill you cannot do yet"],"correct":0,"point":3,"why":{"en":"To see that you know yourself and can improve. 'No real faults' sounds untrue, and a missing main skill is not what they test here.","tr":"Kendini tanıdığını ve gelişebildiğini görmek. 'Hiç gerçek hatam yok' inandırıcı değildir; burada eksik bir ana beceri ölçülmez.","fa":"می‌خواهند ببینند خودت را می‌شناسی و می‌توانی بهتر شوی. «هیچ ایرادی ندارم» باورپذیر نیست و اینجا دنبال مهارت اصلی‌ای که نداری نیستند."}}]},"explain":{"id":"c-int-6-e","course":"interview","unit":"int-6","type":"explain","level":"B1","title":{"en":"Video and recorded interviews","tr":"Görüntülü ve kayıtlı mülakatlar","fa":"مصاحبه‌های تصویری و ضبط‌شده"},"objective":{"en":"After this lesson, you can get ready for live video and recorded interviews, and deal calmly with a technical problem.","tr":"Bu dersin sonunda canlı görüntülü ve kayıtlı mülakatlara hazırlanabilecek ve teknik bir sorunu sakince çözebileceksin.","fa":"بعد از این درس می‌توانی برای مصاحبه‌های تصویری زنده و ضبط‌شده آماده شوی و با یک مشکل فنی آرام برخورد کنی."},"hook":{"en":"A video interview adds one more test: can they see and hear you, and do you stay calm when the technology fails? So find out if it is live or recorded, set up the day before, and learn one short line for problems.","tr":"Görüntülü mülakat bir sınav daha ekler: Seni görüp duyabiliyorlar mı, teknoloji sorun çıkarınca sakin kalıyor musun? Bu yüzden canlı mı kayıtlı mı olduğunu öğren, bir gün önceden hazırlan ve sorunlar için kısa bir cümle öğren.","fa":"مصاحبه‌ی تصویری یک آزمون دیگر هم دارد: تو را می‌بینند و صدایت را می‌شنوند؟ وقتی مشکل فنی پیش می‌آید آرام می‌مانی؟ پس اول ببین مصاحبه زنده است یا ضبط‌شده، روز قبل همه‌چیز را آماده کن و یک جمله‌ی کوتاه برای مشکل‌ها یاد بگیر."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Know which kind it is, then prepare","tr":"Hangi tür olduğunu öğren, sonra hazırlan","fa":"اول ببین کدام نوع است و بعد آماده شو"},"steps":[{"en":"Ask if it is live or recorded, because you prepare differently. Recorded means you answer alone.","tr":"Canlı mı kayıtlı mı olduğunu sor, çünkü hazırlığın farklı olur. Kayıtlı, tek başına cevaplaman demektir.","fa":"بپرس مصاحبه زنده است یا ضبط‌شده، چون آمادگی هر کدام فرق دارد. ضبط‌شده یعنی تنها جواب می‌دهی.","ex":"Recorded: you get a link, and nobody is on the call."},{"en":"Set up the day before, so there is time to fix problems. Test camera, light and sound.","tr":"Bir gün önceden hazırlan; böylece sorunları çözmeye zaman kalır. Kamerayı, ışığı ve sesi dene.","fa":"روز قبل آماده شو تا برای حل مشکل‌ها وقت داشته باشی. دوربین، نور و صدا را امتحان کن.","ex":"Weak: laptop on your knees, window behind you (dark face). Better: laptop on books at eye level, window in front."},{"en":"For key sentences, look at the camera, not your own face. To them, that is eye contact.","tr":"Önemli cümlelerinde kendi yüzüne değil, kameraya bak. Onlar için göz teması budur.","fa":"وقتی جمله‌های مهمت را می‌گویی به دوربین نگاه کن، نه به تصویر خودت. از نظر آن‌ها تماس چشمی یعنی همین.","ex":"Hide your own picture if you can."},{"en":"Recorded: read the rules first, because each employer sets its own limits. Use any practice question offered.","tr":"Kayıtlı: önce kuralları oku, çünkü her işveren kendi sınırlarını koyar. Sunulan deneme sorularını kullan.","fa":"در مصاحبه‌ی ضبط‌شده اول قواعد را بخوان، چون هر کارفرما محدودیت‌های خودش را دارد. اگر سؤال تمرینی هست از آن استفاده کن.","ex":"Deadline, think time, answer time, how many retakes"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Problems right now: present continuous","tr":"Şu anki sorunlar: present continuous","fa":"مشکلِ همین الان: حال استمراری"},"steps":[{"en":"For a problem happening now, use am / is / are + -ing.","tr":"Şu anda olan bir sorun için am / is / are + -ing kullan.","fa":"برای مشکلی که همین الان هست am، is یا are را با فعل ing می‌آوری.","ex":"You're breaking up."},{"en":"Add not to say what isn't working.","tr":"Çalışmayan şeyi söylemek için not ekle.","fa":"برای گفتن چیزی که کار نمی‌کند، بعد از am، is یا are کلمه‌ی not را بیاور.","ex":"I'm not getting any sound."},{"en":"For something always true, use the present simple.","tr":"Her zaman doğru olan bir şey için present simple kullan.","fa":"برای چیزی که همیشه درست است حال ساده می‌آوری.","ex":"My laptop has a good camera."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["A problem now: am / is / are + -ing","You're breaking up."],["Negative","I'm not getting any sound."],["Question","Is my sound working now?"],["Always true: present simple","My laptop has a good camera."]]},"tip":{"en":"Persian uses one present tense for 'now' and 'always', so learners say 'You break up'. Turkish -iyor matches: kesiliyor = is cutting out.","tr":"Türkçedeki '-iyor' burada yardımcı olur: 'ses kesiliyor' = the sound is cutting out. Tuzak, 'You break up' gibi yalın biçimdir.","fa":"در فارسی «صدایت قطع و وصل می‌شود» هم برای «الان» است و هم برای «همیشه»؛ برای همین «You break up» می‌گوییم. انگلیسی برای «همین الان» am، is یا are را با فعل ing می‌آورد: You're breaking up."},"wrong":"Sorry, your sound doesn't work right now.","right":"Sorry, your sound isn't working right now."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"If you cannot get back","tr":"Geri dönemezsen","fa":"اگر نتوانستی برگردی"},"body":{"en":"Keep short notes beside the camera, but don't read them: it shows. If a live call won't reconnect, email the same day with times you are free. If a recorded interview stops, try the same link, then write to your contact.","tr":"Kısa notlarını kameranın yanında tut ama okuma; görüntüde belli olur. Canlı görüşme geri gelmezse aynı gün müsait olduğun saatleri e-postayla yaz. Kayıtlı mülakat durursa aynı bağlantıyı dene, sonra irtibat kişine yaz.","fa":"یادداشت‌های کوتاهت را کنار دوربین بگذار، ولی از رویشان نخوان؛ در تصویر معلوم می‌شود. اگر تماس زنده وصل نشد، همان روز ایمیل بزن و ساعت‌هایی را که آزادی بگو. اگر مصاحبه‌ی ضبط‌شده قطع شد، همان لینک را امتحان کن و بعد به فرد رابط پیام بده."},"phrases":[{"phrase":"Can you hear me okay?","meaning":{"en":"Your first line on any call.","tr":"Her görüşmedeki ilk cümlen.","fa":"جمله‌ی اولت در هر تماس."}},{"phrase":"Sorry, you're breaking up.","meaning":{"en":"Says the sound is cutting out.","tr":"Sesin kesildiğini söyler.","fa":"می‌گوید صدا قطع و وصل می‌شود."}},{"phrase":"Sorry about that, my connection dropped.","meaning":{"en":"One apology, then you continue.","tr":"Bir özür, sonra devam edersin.","fa":"یک عذرخواهی و بعد ادامه می‌دهی."}},{"phrase":"recorded interview","meaning":{"en":"An interview where you record answers alone and the company watches them later.","tr":"Cevaplarını tek başına kaydettiğin ve şirketin sonra izlediği mülakat.","fa":"مصاحبه‌ای که جواب‌ها را تنها ضبط می‌کنی و شرکت بعداً آن‌ها را می‌بیند."}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Handle a dropped call","tr":"Kopan görüşmeyi yönet","fa":"وقتی تماس قطع می‌شود چه بگویی"},"item":"Weak: Oh no, sorry, sorry, my internet is very bad, I'm so sorry, I don't know what happens.","answer":"Sorry about that, my connection dropped. How much of my last answer did you hear?","walk":[{"en":"Say sorry once, then say what happened.","tr":"Bir kez özür dile, sonra ne olduğunu söyle.","fa":"یک بار عذرخواهی کن و بعد بگو چه شد."},{"en":"Ask what they heard, so nothing is lost.","tr":"Bir şey kaybolmasın diye ne duyduklarını sor.","fa":"بپرس چه چیزی را شنیدند تا چیزی از جوابت جا نماند."},{"en":"Go back to your answer, because that is what they came to hear.","tr":"Cevabına dön, çünkü duymak istedikleri şey o.","fa":"برگرد سر جوابت، چون آن‌ها همان را می‌خواهند بشنوند."}]},"quick":{"prompt":"Sorry, I think your sound ___ right now.","options":["is cutting out","cuts out","cut out"],"correct":0,"why":{"en":"is cutting out: the problem is happening now, so use am / is / are + -ing.","tr":"is cutting out: sorun şu anda oluyor, o yüzden am / is / are + -ing.","fa":"جواب is cutting out است، چون مشکل همین حالا در جریان است؛ برای همین am، is یا are را با فعل ing می‌آوریم."}},"remember":{"en":"One problem, one apology, then back to your answer. You can now prepare for both kinds of video interview and handle a dropped call calmly. Next, you practise a call with problems and write the email after one.","tr":"Bir sorun, bir özür, sonra cevabına dön. Artık iki tür görüntülü mülakata da hazırlanabilir ve kopan bir görüşmeyi sakince yönetebilirsin. Sırada sorunlu bir görüşme alıştırması ve kopan görüşmenin ardından bir e-posta yazmak var.","fa":"برای هر مشکل یک بار عذرخواهی کن و برگرد سر جوابت. حالا می‌توانی برای هر دو نوع مصاحبه‌ی تصویری آماده شوی و با قطع شدن تماس آرام برخورد کنی. در ادامه یک تماس پر از مشکل را تمرین می‌کنی و ایمیل بعد از قطع تماس را می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Looking back: should have, could have","tr":"Geriye bakmak: should have, could have","fa":"نگاه به گذشته: should have و could have"},"steps":[{"en":"Didn't do it, but it was a good idea: should have + past participle.","tr":"Yapmadın ama iyi bir fikirdi: should have + üçüncü hâl.","fa":"should have همان «باید ... می‌کردم» فارسی است: کاری که باید می‌کردی و نکردی.","ex":"I should have tested my internet."},{"en":"Did it, but it was a bad idea: shouldn't have.","tr":"Yaptın ama kötü bir fikirdi: shouldn't have.","fa":"اگر کاری را کردی و فکر بدی بود، می‌گویی shouldn't have.","ex":"I shouldn't have read my notes."},{"en":"A chance you missed: could have.","tr":"Kaçırdığın bir fırsat: could have.","fa":"برای فرصتی که از دست دادی could have می‌آوری.","ex":"I could have asked about the team."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["should have + past participle: you didn't do it","I should have tested my internet."],["shouldn't have + past participle: you did it","I shouldn't have read my notes."],["could have + past participle: a missed chance","I could have asked about the team."]]},"body":{"en":"B2: in your writing or speaking, add one sentence that looks back: 'I should have...' or 'I could have...'.","tr":"B2: yazında ya da konuşmanda geriye bakan bir cümle ekle: 'I should have...' ya da 'I could have...'.","fa":"در مسیر B2: در نوشته یا صحبتت جمله‌ای اضافه کن که به گذشته نگاه می‌کند: «I should have...» یا «I could have...»."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
